import numpy as np, librosa
y, sr = librosa.load('input.wav', sr=None, mono=True)
N_FFT=2048; HOP=512
Sref = np.abs(librosa.stft(y, n_fft=N_FFT, hop_length=HOP))
print('=== TRUE magnitude, sweep init/momentum/iter/seed ===')
best=None
for init in ['random', None]:
  for mom in [0.0, 0.9, 0.99]:
    for it in [32, 64, 128]:
      for seed in [0,1,2,3,4]:
        yr = librosa.griffinlim(Sref, n_iter=it, hop_length=HOP, n_fft=N_FFT, length=len(y), momentum=mom, init=init, random_state=seed)
        L=min(len(y),len(yr)); ref=y[:L].astype(np.float64); rec=yr[:L].astype(np.float64)
        snr = 10*np.log10(np.sum(ref**2)/np.sum((ref-rec)**2))
        if best is None or snr>best[0]:
            best=(snr,init,mom,it,seed)
        if snr>0: print(f'init={init} mom={mom} it={it} seed={seed} SNR={snr:.3f} ***')
print('BEST', best)
" 2>&1 | grep -v Warning
